/* Férias: importação recorrente do relatório de programação da contabilidade. */
(function(root){'use strict';
const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toLowerCase();
const iso=x=>/^\d\d\/\d\d\/\d{4}$/.test(x||'')?x.slice(6)+'-'+x.slice(3,5)+'-'+x.slice(0,2):'';
const num=x=>/^\d+$/.test(x||'')?Number(x):0;
const label=s=>root.EngefexNameCase?root.EngefexNameCase(s):s;
async function extract(file){const pdf=await import('./vendor/pdf-4.10.38.min.mjs');const doc=await pdf.getDocument({data:new Uint8Array(await file.arrayBuffer()),disableWorker:true}).promise;const rows=[];
for(let p=1;p<=doc.numPages;p++){const page=await doc.getPage(p),items=(await page.getTextContent()).items;const grouped=new Map();
for(const t of items){const tx=String(t.str||'').trim(),x=t.transform?.[4],y=t.transform?.[5];if(!tx||!Number.isFinite(x)||!Number.isFinite(y))continue;const rowY=Math.round(y*2)/2;const key=[...grouped.keys()].find(k=>Math.abs(k-rowY)<=2)||rowY;grouped.set(key,[...(grouped.get(key)||[]),{x,text:tx}])}
for(const parts of grouped.values()){const at=(a,b)=>parts.filter(q=>q.x>=a&&q.x<b).sort((x,y)=>x.x-y.x).map(x=>x.text).join(' ').trim();const code=at(18,38),name=at(38,205),admission=at(205,255),periodStart=at(358,420),periodEnd=at(420,478),deadline=at(681,732);if(!/^\d+$/.test(code)||!name||!iso(admission)||!iso(periodStart)||!iso(periodEnd))continue;
rows.push({code,name:label(name),admissionDate:iso(admission),periodStart:iso(periodStart),periodEnd:iso(periodEnd),deadline:iso(deadline),entitlement:num(at(605,637))||30,taken:num(at(637,659)),reportedRemaining:num(at(660,680)),absenceDays:num(at(730,756)),absenceCount:num(at(756,790)),sourcePage:p});}}
if(!rows.length)throw Error('Não identifiquei as linhas do relatório. Use o PDF de Programação de Férias da contabilidade, com texto selecionável.');
return rows;}
function calendar(s){const now=today().slice(0,7),selectedMonth=(window.engefexVacationMonth||now),first=new Date(selectedMonth+'-01T12:00:00'),start=new Date(first);start.setDate(1-first.getDay());const ds=[];for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const day=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');const count=records(s).filter(r=>r.start&&r.end&&day>=r.start&&day<=r.end&&r.status!=='Cancelado').length;ds.push('<div class="hr-vac-calendar-day '+(day.slice(0,7)===selectedMonth?'':'muted')+'"><strong>'+d.getDate()+'</strong>'+(count?'<span>'+count+' férias</span>':'')+'</div>')}return '<section class="panel hr-panel"><div class="panel-head"><h2>Calendário de férias</h2><label>Mês <input id="vacCalendarMonth" type="month" value="'+selectedMonth+'"></label></div><div class="hr-vac-calendar">'+['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=>'<div class="hr-vac-calendar-head">'+x+'</div>').join('')+ds.join('')+'</div></section>';}
function ui(s){const list=s.hrVacations||[],people=s.hrEmployees||[];return '<section class="page-head hr-hero"><div><p class="hr-eyebrow">ENGEFEX · RECURSOS HUMANOS</p><h1>Férias</h1><p>Programação, vencimentos e controle de dias compensados.</p></div></section><section class="panel hr-panel"><div class="panel-head"><div><h2>Importar programação de férias</h2><p class="hr-panel-subtitle">Atualize sempre com o PDF padrão da contabilidade. Funcionários ausentes serão cadastrados automaticamente.</p></div><label class="button primary">Importar PDF<input id="vacPdf" type="file" accept=".pdf,application/pdf" hidden></label></div><div id="vacImportStatus" role="status"></div></section><section class="panel hr-panel"><div class="panel-head"><h2>Fichas e saldo de férias</h2></div><div class="hr-vac-table-wrap"><table><thead><tr><th>Funcionário</th><th>Período aquisitivo</th><th>Limite para gozo</th><th>Direito</th><th>Gozados</th><th>Compensados*</th><th>Saldo interno</th><th>Ação</th></tr></thead><tbody>'+list.map(r=>{const p=people.find(x=>x.id===r.employeeId),used=(r.discounts||[]).reduce((a,x)=>a+Number(x.days||0),0),balance=Number(r.entitlement??30)-Number(r.taken||0)-used;return '<tr><td><strong>'+h(p?.name||'Funcionário não encontrado')+'</strong></td><td>'+h(r.periodStart)+' a '+h(r.periodEnd)+'</td><td>'+h(r.deadline||'—')+'</td><td>'+Number(r.entitlement??30)+'</td><td>'+Number(r.taken||0)+'</td><td>'+used+'</td><td><strong>'+balance+'</strong></td><td><button class="button secondary" data-vac-edit="'+h(r.id)+'">Abrir ficha</button></td></tr>'}).join('')+'</tbody></table></div><p class="hr-panel-subtitle">*Compensações internas de folgas: não alteram automaticamente o direito legal de férias nem substituem a folha da contabilidade.</p></section><dialog class="hr-editor hr-vac-dialog" id="vacDialog"><div class="hr-editor-header"><div><small>ENGEFEX · CONTROLE INDIVIDUAL</small><h2 id="vacDialogTitle">Ficha de férias</h2></div><button type="button" class="hr-editor-close" data-vac-close>×</button></div><div class="hr-vac-dialog-body"><div id="vacSummary"></div><h3>Dias descontados / compensações internas</h3><p class="hr-panel-subtitle">Preencha uma linha para cada compensação. É um controle administrativo separado das férias legais.</p><div class="hr-vac-table-wrap"><table><thead><tr><th>Data</th><th>Dias descontados</th><th>OBS</th><th></th></tr></thead><tbody id="vacDiscountRows"></tbody></table></div><button class="button secondary" id="vacAddRow" type="button">+ Linha</button><p id="vacBalance"></p></div><footer class="hr-editor-footer"><button type="button" class="button secondary" id="vacWord">Aviso Word</button><button type="button" class="button secondary" id="vacPdfNotice">Aviso PDF</button><button type="button" class="button secondary" id="vacReceiptWord">Recibo Word</button><button type="button" class="button secondary" id="vacReceiptPdf">Recibo PDF</button><button type="button" class="button secondary" data-vac-close>Fechar</button><button type="button" class="button primary" id="vacSave">Salvar</button></footer></dialog>';}
function bind(s,persist,render,notify){const input=document.getElementById('vacPdf');if(!input)return;const monthEl=document.getElementById('vacCalendarMonth');if(monthEl)monthEl.onchange=()=>{window.engefexVacationMonth=monthEl.value;render()};input.onchange=async()=>{try{const file=input.files?.[0];if(!file)return;const out=document.getElementById('vacImportStatus');out.textContent='Lendo o relatório…';const rows=await extract(file);const staff=s.hrEmployees||[],vac=s.hrVacations||[];let missing=0,dups=[];const groups=[];for(const row of rows){const existing=staff.filter(e=>String(e.employeeCode||'')===row.code||norm(e.name)===norm(row.name));if(existing.length>1){dups.push(row.name);continue}if(!existing.length)missing++;groups.push({row,existing:existing[0]})}if(dups.length)throw Error('Correspondências ambíguas: '+dups.join(', '));const permission=root.EngefexAccess;if(!permission?.canWrite('hr-vacations')||(missing&&!permission.canWrite('hr-employees')))throw Error('Para importar, é necessário editar Férias e, quando houver pessoas novas, Funcionários.');
out.textContent=rows.length+' linhas reconhecidas · '+missing+' novos funcionários · '+(rows.length-missing)+' existentes.';
if(!confirm('Importar '+groups.length+' linhas do PDF, criando '+missing+' funcionário(s) ausente(s)? O histórico de compensações será preservado.'))return;
const next=structuredClone(s);next.hrEmployees=next.hrEmployees||[];next.hrVacations=next.hrVacations||[];let created=0,updated=0;
for(const {row,existing} of groups){let person=existing&&next.hrEmployees.find(e=>e.id===existing.id);if(!person){person={id:crypto.randomUUID(),name:row.name,employeeCode:row.code,admissionDate:row.admissionDate,active:true,employmentStatus:'ativo',category:'outros',companyStatus:'engefex'};next.hrEmployees.push(person);created++}else{if(!person.employeeCode)person.employeeCode=row.code;if(!person.admissionDate)person.admissionDate=row.admissionDate}
let record=next.hrVacations.find(v=>v.employeeId===person.id&&v.periodStart===row.periodStart&&v.periodEnd===row.periodEnd);
if(!record){record={id:crypto.randomUUID(),employeeId:person.id,discounts:[],status:'Planejado'};next.hrVacations.push(record)}else updated++;
Object.assign(record,{periodStart:row.periodStart,periodEnd:row.periodEnd,deadline:row.deadline,entitlement:row.entitlement,taken:row.taken,reportedRemaining:row.reportedRemaining,absenceDays:row.absenceDays,absenceCount:row.absenceCount,source:'Programação de férias PDF'});}
await persist(next,'Programação de férias importada.');notify('Importados '+rows.length+' registros; '+created+' funcionário(s) criado(s); '+updated+' período(s) atualizados.');render();
}catch(e){document.getElementById('vacImportStatus').textContent=e.message;notify(e.message)}};
const dialog=document.getElementById('vacDialog');let selected=null;document.querySelectorAll('[data-vac-edit]').forEach(b=>b.onclick=()=>{selected=(s.hrVacations||[]).find(v=>v.id===b.dataset.vacEdit);if(!selected)return;const p=(s.hrEmployees||[]).find(e=>e.id===selected.employeeId);document.getElementById('vacDialogTitle').textContent=p?.name||'Ficha de férias';document.getElementById('vacSummary').innerHTML='<p><strong>Admissão:</strong> '+h(p?.admissionDate||'—')+' · <strong>Aquisitivo:</strong> '+h(selected.periodStart)+' a '+h(selected.periodEnd)+' · <strong>Limite gozo:</strong> '+h(selected.deadline||'—')+'</p><p><strong>Direito:</strong> '+Number(selected.entitlement??30)+' dias · <strong>Gozados informados:</strong> '+Number(selected.taken||0)+' dias</p>';const tbody=document.getElementById('vacDiscountRows');tbody.innerHTML='';(selected.discounts||[]).forEach(x=>addLine(x));if(!selected.discounts?.length)addLine();update();dialog.showModal()});
const tbody=document.getElementById('vacDiscountRows');function addLine(x={}){const tr=document.createElement('tr');tr.innerHTML='<td><input type="date" class="vac-date" value="'+h(x.date||'')+'"></td><td><input type="number" class="vac-days" min="0" step="0.5" value="'+h(x.days??'')+'" style="width:110px"></td><td><input class="vac-obs" placeholder="Ex.: folga compensada" value="'+h(x.obs||'')+'"></td><td><button type="button" class="button secondary vac-remove">Excluir</button></td>';tr.querySelector('.vac-remove').onclick=()=>{tr.remove();update()};tr.querySelector('.vac-days').oninput=update;tbody.append(tr);update()}
function update(){if(!selected)return;const used=[...tbody.querySelectorAll('.vac-days')].reduce((a,i)=>a+Number(i.value||0),0);document.getElementById('vacBalance').textContent='Saldo interno: '+(Number(selected.entitlement??30)-Number(selected.taken||0)-used)+' dia(s) · Descontados: '+used+' dia(s)';}
function docLines(receipt){const p=employee(s,selected.employeeId)||{},title=receipt?'RECIBO DE FÉRIAS':'AVISO DE FÉRIAS';const lines=[title,'Engefex Estruturas Metálicas Ltda.','Funcionário: '+(p.name||''),'Admissão: '+(p.admissionDate||''),'Período aquisitivo: '+(selected.periodStart||'')+' a '+(selected.periodEnd||''),'Período programado: '+(selected.start||'não informado')+' a '+(selected.end||'não informado'),'Dias de direito informados: '+(selected.entitlement??30),'Dias gozados informados: '+(selected.taken??0)];if(receipt)lines.push('ATENÇÃO: valores de remuneração, abono, 1/3 constitucional e descontos devem ser preenchidos e conferidos pela contabilidade antes da assinatura.');else lines.push('Este aviso é um modelo administrativo. Confirme antecedência legal, datas e condições junto ao RH/contabilidade.');lines.push('Data: ____/____/________','Assinatura do funcionário: __________________________________','Assinatura do responsável: __________________________________');return lines}
function dl(data,type,name){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
async function exportDocument(receipt,pdf){if(!selected)return;const lines=docLines(receipt),name=(receipt?'recibo':'aviso')+'-ferias-'+selected.id;if(pdf){const P=root.PDFLib;if(!P)throw Error('Biblioteca PDF indisponível');const d=await P.PDFDocument.create(),page=d.addPage([595,842]),font=await d.embedFont(P.StandardFonts.Helvetica);lines.forEach((t,i)=>page.drawText(String(t).normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^\\x20-\\x7e]/g,' '),{x:45,y:780-i*32,size:i===0?17:10,font,maxWidth:500}));dl(await d.save(),'application/pdf',name+'.pdf')}else{const docx=root.docx;if(!docx?.Document||!docx?.Packer)throw Error('Biblioteca Word indisponível');const d=new docx.Document({sections:[{children:lines.map((t,i)=>new docx.Paragraph({text:t,spacing:{after:i===0?400:210}}))}]});dl(await docx.Packer.toBlob(d),'application/vnd.openxmlformats-officedocument.wordprocessingml.document',name+'.docx')}}
for(const [id,receipt,pdf] of [['vacWord',false,false],['vacPdfNotice',false,true],['vacReceiptWord',true,false],['vacReceiptPdf',true,true]]){const button=document.getElementById(id);if(button)button.onclick=async()=>{try{await exportDocument(receipt,pdf)}catch(e){notify(e.message)}}}
document.getElementById('vacAddRow').onclick=()=>addLine();dialog.querySelectorAll('[data-vac-close]').forEach(b=>b.onclick=()=>dialog.close());document.getElementById('vacSave').onclick=async()=>{if(!root.EngefexAccess?.canWrite('hr-vacations'))return notify('Sem permissão para editar férias');const discounts=[...tbody.querySelectorAll('tr')].map(tr=>({id:crypto.randomUUID(),date:tr.querySelector('.vac-date').value,days:Number(tr.querySelector('.vac-days').value||0),obs:tr.querySelector('.vac-obs').value.trim()})).filter(x=>x.days>0||x.obs||x.date);if(discounts.some(x=>x.days<0||!Number.isFinite(x.days)))return notify('Dias inválidos.');const remain=Number(selected.entitlement??30)-Number(selected.taken||0)-discounts.reduce((a,x)=>a+x.days,0);if(remain<0&&!confirm('O saldo ficará negativo. Confirmar lançamento?'))return;const next=structuredClone(s);const r=next.hrVacations.find(x=>x.id===selected.id);r.discounts=discounts;try{await persist(next,'Compensações de férias salvas.');dialog.close();render()}catch(e){notify(e.message)}};}
root.EngefexVacationControl={page:ui,attach:bind};
})(window);